                    preexistingXp.motionY = 0.0D;
                    preexistingXp.motionZ = 0.0D;
                    preexistingXp.rotationYaw = 0.0F;
                    preexistingXp.xpOrbAge = preexistingXpExpires ? 5999 : 10;
