                    (net.minecraft.tileentity.TileEntityCommandBlock)tile;
                command.getCommandBlockLogic().setSuccessCount(success);
                command.markDirty();
                world.updateComparatorOutputLevel(
                    pos, world.getBlockState(pos).getBlock());
